<?php
require_once __DIR__ . '/inc/mother_session.php';
$recipients=[];$recipientIds=[];
if($mother['chw_id'])$recipientIds[]=(int)$mother['chw_id'];
if($mother['facility_id']){$q=$db->prepare('SELECT u_id FROM tbl_users WHERE facility_id=? AND log_role IN (2,4) AND is_active=1 ORDER BY log_role,u_id');$q->execute([(int)$mother['facility_id']]);$recipientIds=array_merge($recipientIds,array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)));}
// Keep an existing administrator thread reachable when an admin initiated a
// message to this mother; admins are not otherwise offered as chat contacts.
$history=$db->prepare("SELECT DISTINCT CASE WHEN x.sender_id=? THEN x.receiver_id ELSE x.sender_id END partner_id FROM tbl_messages x JOIN tbl_users p ON p.u_id=CASE WHEN x.sender_id=? THEN x.receiver_id ELSE x.sender_id END WHERE x.mother_id=? AND (x.sender_id=? OR x.receiver_id=?) AND p.is_active=1 AND (p.log_role=1 OR (p.log_role=3 AND p.u_id=?) OR (p.log_role IN (2,4) AND p.facility_id=?))");
$history->execute([(int)$_SESSION['u_id'],(int)$_SESSION['u_id'],$motherId,(int)$_SESSION['u_id'],(int)$_SESSION['u_id'],(int)($mother['chw_id']??0),(int)($mother['facility_id']??0)]);
$recipientIds=array_merge($recipientIds,array_map('intval',$history->fetchAll(PDO::FETCH_COLUMN)));
$recipientIds=array_values(array_unique($recipientIds));if($recipientIds){$marks=implode(',',array_fill(0,count($recipientIds),'?'));$q=$db->prepare("SELECT u_id,f_name,l_name FROM tbl_users WHERE u_id IN ($marks) AND is_active=1 ORDER BY f_name");$q->execute($recipientIds);$recipients=$q->fetchAll(PDO::FETCH_ASSOC);}
$symptoms=$db->query('SELECT symptom_id,symptom_name,symptom_name_rw FROM tbl_symptoms WHERE is_active=1 ORDER BY symptom_name')->fetchAll(PDO::FETCH_ASSOC);
$page_title=$t('Live chat');include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<section class="panel mcare-messages-page"><header class="panel-heading"><h2 class="panel-title"><?=$t('Live chat with your care team')?></h2></header><div class="panel-body"><p><?=$t('Chat is with a human care-team member and is not continuously monitored. Choose who to contact. Replies appear automatically while this page is open. For emergencies, seek care now instead of waiting for chat.')?></p>
<?php if($recipients): ?><div class="form-group mcare-chat-contact"><label for="mcare-chat-partner"><?=$t('Choose a care-team member')?></label><select id="mcare-chat-partner" class="form-control"><option value=""><?=$t('Choose a care-team member')?></option><?php foreach($recipients as $r): ?><option value="<?=$r['u_id']?>"><?=$e($r['f_name'].' '.$r['l_name'])?></option><?php endforeach; ?></select></div><div id="mcare-chat-status" class="mcare-chat-status text-muted" role="status" aria-live="polite"><?=$t('Select a care-team member to open a conversation.')?></div><div id="mcare-chat-log" class="mcare-chat-log" role="log" aria-live="polite" aria-relevant="additions text"></div>
<form id="mcare-chat-form"><fieldset class="form-group mcare-checkbox-group" aria-labelledby="mcare-chat-topic-label"><legend id="mcare-chat-topic-label" class="control-label"><?=$t('What would you like help with?')?></legend><div class="mcare-check-grid"><?php foreach(['Symptoms or how I feel','Pregnancy questions','After-birth or postpartum care','Nutrition','Appointment or referral','Other'] as $topic): ?><label class="mcare-choice"><input type="checkbox" name="topics[]" value="<?=$e($topic)?>"><span><?=$e($t($topic))?></span></label><?php endforeach; ?></div></fieldset><fieldset class="form-group mcare-checkbox-group" aria-labelledby="mcare-chat-symptoms-label"><legend id="mcare-chat-symptoms-label" class="control-label"><?=$t('Related symptoms (optional)')?></legend><div class="mcare-check-grid mcare-symptom-grid"><?php foreach($symptoms as $s): ?><label class="mcare-choice"><input type="checkbox" name="symptoms[]" value="<?=(int)$s['symptom_id']?>"><span><?=$e(($language==='rw'&&$s['symptom_name_rw'])?$s['symptom_name_rw']:$s['symptom_name'])?></span></label><?php endforeach; ?></div><small class="text-muted"><?=$t('You can select more than one. This helps organize your message for the professional; it does not provide a diagnosis.')?></small></fieldset><div class="form-group"><label for="mcare-chat-message"><?=$t('Your message')?></label><textarea id="mcare-chat-message" class="form-control" rows="3" maxlength="4000" required></textarea></div><button id="mcare-chat-send" class="btn btn-primary" type="submit"><?=$t('Send message')?></button></form>
<?php else: ?><p class="alert alert-info"><?=$t('No care-team member is assigned yet. Contact your health facility or CHW to update your care-team assignment.')?></p><?php endif; ?></div></section>
</section></div><?php include 'inc/footer.php';include 'inc/scripts.php'; ?>
<?php if($recipients): ?><script>
(function(){
const partner=document.getElementById('mcare-chat-partner'),log=document.getElementById('mcare-chat-log'),status=document.getElementById('mcare-chat-status'),form=document.getElementById('mcare-chat-form'),input=document.getElementById('mcare-chat-message'),send=document.getElementById('mcare-chat-send');
const currentUser=<?=json_encode((int)$_SESSION['u_id'])?>,csrf=<?=json_encode($_SESSION['csrf_token'])?>,youLabel=<?=json_encode($t('You'))?>,teamLabel=<?=json_encode($t('Care team'))?>,chatPrefix=<?=json_encode($t('Chat with'))?>,refreshLabel=<?=json_encode($t('New messages refresh automatically.'))?>;
let timer=null,busy=false,seen='';
function render(data,partnerId){if(!data||!Array.isArray(data.messages)||partner.value!==String(partnerId))return;const key=partnerId+':'+data.messages.map(m=>m.message_id).join(',');if(key!==seen){const atBottom=log.scrollHeight-log.scrollTop-log.clientHeight<48||log.scrollHeight<=log.clientHeight;seen=key;log.replaceChildren();if(!data.messages.length){const empty=document.createElement('div');empty.className='mcare-chat-empty';empty.textContent=<?=json_encode($t('No messages yet. Send a message to start this conversation.'))?>;log.append(empty);}data.messages.forEach(m=>{const row=document.createElement('div');row.className='mcare-chat-row '+(Number(m.sender_id)===currentUser?'is-mine':'is-team');const bubble=document.createElement('div');bubble.className='mcare-chat-bubble '+(Number(m.sender_id)===currentUser?'is-mine':'is-team');const name=document.createElement('strong');name.textContent=Number(m.sender_id)===currentUser?youLabel:teamLabel;const body=document.createElement('div');body.className='mcare-chat-message';body.textContent=m.message_body;const date=document.createElement('small');date.className='mcare-chat-time';date.textContent=m.sent_at;bubble.append(name,body,date);row.append(bubble);log.append(row);});if(atBottom)log.scrollTop=log.scrollHeight;}status.textContent=chatPrefix+' '+data.partner.name+' · '+refreshLabel;}
async function refresh(){const requestedPartner=partner.value;if(!requestedPartner||busy)return;try{const r=await fetch('mother_chat?partner_id='+encodeURIComponent(requestedPartner),{headers:{Accept:'application/json'},cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Chat could not be loaded.');render(d,requestedPartner);}catch(err){if(partner.value===requestedPartner)status.textContent=err.message;}}
function start(){if(timer)clearInterval(timer);seen='';log.replaceChildren();if(!partner.value){status.textContent=<?=json_encode($t('Select a care-team member to open a conversation.'))?>;return;}status.textContent=<?=json_encode($t('Loading conversation…'))?>;refresh();timer=setInterval(()=>{if(!document.hidden)refresh();},5000);}
partner.addEventListener('change',start);
form.addEventListener('submit',async e=>{e.preventDefault();if(!partner.value||busy)return;const message=input.value.trim(),selectedPartner=partner.value,selectedTopics=Array.from(document.querySelectorAll('input[name="topics[]"]:checked'));if(!message)return;if(!selectedTopics.length){status.textContent=<?=json_encode($t('Choose a topic'))?>;return;}busy=true;send.disabled=true;partner.disabled=true;status.textContent=<?=json_encode($t('Sending…'))?>;try{const p=new URLSearchParams();p.set('_csrf',csrf);p.set('partner_id',selectedPartner);selectedTopics.forEach(o=>p.append('topics[]',o.value));p.set('message_body',message);Array.from(document.querySelectorAll('input[name="symptoms[]"]:checked')).forEach(o=>p.append('symptoms[]',o.value));const r=await fetch('mother_chat?partner_id='+encodeURIComponent(selectedPartner),{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:p.toString()});const d=await r.json();if(!r.ok)throw new Error(d.error||'Message was not sent.');input.value='';document.querySelectorAll('input[name="topics[]"],input[name="symptoms[]"]').forEach(o=>o.checked=false);seen='';render(d,selectedPartner);}catch(err){status.textContent=err.message;}finally{busy=false;send.disabled=false;partner.disabled=false;}});
if(partner.options.length>1){partner.selectedIndex=1;start();}
})();
</script><?php endif; ?>
